/*
 * SlickNav-compatible mobile menu file for Kylan Green's portfolio.
 * API used: $('#nav_menu').slicknav({ prependTo: '#mobile_menu' });
 * Date Developed: 09-24-26
 * Date Tested: 09-24-26
 */
(function ($) {
    "use strict";

    $.fn.slicknav = function (options) {
        var settings = $.extend({
            label: "MENU",
            prependTo: "body",
            closeOnClick: false
        }, options);

        return this.each(function () {
            var original = $(this);
            var mobile = original.clone();
            var container = $(settings.prependTo);

            mobile.removeAttr("id");
            mobile.find("[id]").removeAttr("id");
            mobile.addClass("slicknav_nav");

            var menu = $("<div class='slicknav_menu'></div>");
            var button = $(
                "<button type='button' class='slicknav_btn' aria-expanded='false' aria-label='Open menu'>" +
                "<span class='slicknav_menutxt'>" + settings.label + "</span>" +
                "<span class='slicknav_icon'>" +
                "<span class='slicknav_icon-bar'></span>" +
                "<span class='slicknav_icon-bar'></span>" +
                "<span class='slicknav_icon-bar'></span>" +
                "</span></button>"
            );

            menu.append(button).append(mobile);
            container.prepend(menu);
            mobile.hide();

            button.on("click", function () {
                mobile.stop(true, true).slideToggle(200);
                var expanded = button.attr("aria-expanded") === "true";
                button.attr("aria-expanded", String(!expanded));
            });

            if (settings.closeOnClick) {
                mobile.find("a").on("click", function () {
                    mobile.stop(true, true).slideUp(200);
                    button.attr("aria-expanded", "false");
                });
            }
        });
    };
}(jQuery));
